#!/usr/bin/env python3
"""Build ECKEY THUMP's original 1,200-entry v0.9 editorial draft.

Every word and phrase bank in this script was authored for this project. The
combinations are curated patterns, not copied competitor decks. Final editorial
and real-party playtests remain necessary before commercial distribution.
"""
import json, re, random, hashlib
from pathlib import Path
random.seed(90119)
root=Path(__file__).resolve().parents[1]
entries=[]
TARGET={
 'responses':{'clean':140,'cheeky':300,'adult':280},
 'cardPrompts':{'clean':20,'cheeky':65,'adult':65},
 'witPrompts':{'clean':10,'cheeky':50,'adult':50},
 'contextPrompts':{'clean':10,'cheeky':28,'adult':27},
 'doublePrompts':{'clean':8,'cheeky':24,'adult':23},
 'finalPrompts':{'clean':7,'cheeky':20,'adult':18},
 'finalWords':{'clean':5,'cheeky':10,'adult':10},
 'contracts':{'clean':5,'cheeky':13,'adult':12},
}
assert sum(sum(z.values()) for z in TARGET.values())==1200

def splititems(s):
 return [p.strip() for p in s.strip().split('|') if p.strip()]

def add(kind,tier,items):
 n=TARGET[kind][tier]
 cleaned=[];seen=set()
 for v in items:
  v=' '.join(v.strip().split())
  if v.casefold() not in seen and v:
   cleaned.append(v);seen.add(v.casefold())
 if len(cleaned)<n:
  raise ValueError(f'{kind}/{tier}: {len(cleaned)} < {n}')
 for i,text in enumerate(cleaned[:n],1):
  assert 2<len(text)<=175,(kind,tier,text)
  entries.append({'id':f'et09-{kind.lower()}-{tier}-{i:03d}', 'kind':kind, 'rating':tier, 'text':text, 'pack':'eckey-after-dark-09', 'tags':tag_for(kind,tier,text), 'editorialStatus':'draft'})
 print(f'{kind:16} {tier:7} {n:3} / candidate {len(cleaned)}')

def tag_for(kind,tier,text):
 tags=[tier]
 lex=text.lower()
 for name,words in [('british',['council','pub','hen party','stag do','roundabout','vicar','bin','bingo','wetherspoons','high street','pound','seaside','queue','chippy','biscuit']),('dating',['date','romance','dating','ex','relationship','flirt','kiss','lover','tinder']),('workplace',['office','boss','hr ','meeting','colleague','payroll','job','manager']),('party',['party','wedding','hen','stag','karaoke','drunk','pub','bar','cocktail','hangover']),('absurd',['pigeon','goose','llama','badger','hamster','turnip','teapot','trolley','ferret'])]:
  if any(w in lex for w in words):tags.append(name)
 return tags

