# or scraped from competitors. Enforce exact count, tier split, uniqueness and limits.
assert len(entries)==1200,len(entries)
assert len({x['id'] for x in entries})==1200
texts={}
for e in entries:
 key=e['text'].casefold()
 if key in texts: raise ValueError(f'Duplicate text: {e["id"]} / {texts[key]}')
 texts[key]=e['id']
 assert not re.search(r'(?i)https?://|www\.', e['text'])
 assert not any(w in e['text'].lower() for w in ['kill yourself','racial slur','underage','child porn'])
obj={'id':'eckey-after-dark-09','version':'0.9.0','status':'editorial-draft','description':'1,200 original authored and structured content entries. British cheeky/adult comedy. Requires playtesting and editorial approval before sale.','entries':entries}
out=root/'server/packs/after-dark-v09.json'
out.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
